  if (def.learnedSpellIds) monsterDef.learnedSpellIds = def.learnedSpellIds;
  if (def.maxMana != null) monsterDef.maxMana = def.maxMana;
  if (def.manaRegen != null) monsterDef.manaRegen = def.manaRegen;

